    reg [99:0] expected_q;

    // Task to check output
    task check_output(input [99:0] exp);
        begin
            @(posedge clk);
            #1; // Wait slightly after clock edge for DUT update
            if (q !== exp) begin
                $display("Time %0t: Mismatch! Got 0%h, Expected 0%h (load=%b, ena=%b)", 
                         $time, q, exp, load, ena);
                errors = errors + 1;
            end
        end
    endtask

    // 3. Stimulus & self-checking:
