        // Initialize signals
        load = 0;
        ena  = 2'b00;
        data = 100'h0;

        // Apply reset / initial load
        @(posedge clk);
        load = 1;
        data = 100'h123456789ABCDEF0123456789A; // Some pattern with top bit set/clear
        expected_q = data;
        check_output(expected_q);

        // Test no rotation (ena = 2'b00)
        load = 0;
        ena  = 2'b00;
        expected_q = expected_q;
        check_output(expected_q);

        // Test no rotation (ena = 2'b11)
        ena  = 2'b11;
        expected_q = expected_q;
        check_output(expected_q);

        // Test rotate right by one bit (ena = 2'b01) a few times
        ena = 2'b01;
        repeat (5) begin
            expected_q = {expected_q[0], expected_q[99:1]};
            check_output(expected_q);
        end

        // Test rotate left by one bit (ena = 2'b10) a few times
        ena = 2'b10;
        repeat (5) begin
            expected_q = {expected_q[98:0], expected_q[99]};
            check_output(expected_q);
        end

        // Test synchronous load overriding rotation
        load = 1;
        data = 100'hFEDCBA9876543210FEDCBA9876;
        expected_q = data;
        check_output(expected_q);

        // Rotate right again from new loaded value
        load = 0;
        ena  = 2'b01;
        repeat (3) begin
            expected_q = {expected_q[0], expected_q[99:1]};
            check_output(expected_q);
        end

        // Final result check
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
